sparql:
prefix io: <http://www.semanticweb.org/luciana/ontologies/2024/8/inmontology#>
prefix brick: <https://brickschema.org/schema/Brick#>
prefix dc: <http://purl.org/dc/elements/1.1/>
prefix dcterms: <http://purl.org/dc/terms/>
prefix foaf: <http://xmlns.com/foaf/0.1/>
prefix gr: <http://purl.org/goodrelations/v1#>
prefix ns: <http://www.w3.org/2003/06/sw-vocab-status/ns#>
prefix owl: <http://www.w3.org/2002/07/owl#>
prefix pronto: <https://raw.githubusercontent.com/fdioguardi/pronto/main/ontology/pronto.owl#>
prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#>
prefix rec: <https://w3id.org/rec#>
prefix sioc: <http://rdfs.org/sioc/ns#>
prefix skos: <http://www.w3.org/2004/02/skos/core#>
prefix time: <http://www.w3.org/2006/time#>
prefix xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?year ?month (AVG(?valorPorM2) AS ?promedioUSD)
WHERE {
  ?listing a pronto:RealEstateListing ;
           sioc:about ?inmueble ;
           io:hasFeature ?featurePrecio .

  ?inmueble a io:Apartment ;
             io:hasFeature ?featureDireccion ;
             rec:includes ?site .

  ?featureDireccion a io:Address ;
                    io:hasValue ?direccion .
  ?direccion a io:PostalAddress ;
             io:city io:district_Buenos_Aires_La_Plata.

  ?featurePrecio a io:Price ;
                 io:hasValue ?precioNode ;
                 time:hasTime ?fechaNode .
  ?precioNode a gr:UnitPriceSpecification ;
              gr:hasCurrency ?moneda ;
              gr:hasCurrencyValue ?precio ;
              gr:priceType 'BASE'^^xsd:string .

  ?fechaNode a time:Instant ;
             time:inXSDDateTimeStamp ?fechaDelListing .

  ?site a rec:Site ;
        io:hasFeature ?featureSuperficie .
  ?featureSuperficie a io:Surface ;
                     io:hasValue ?superficieNode .
  ?superficieNode a pronto:SizeSpecification ;
                  gr:hasUnitOfMeasurement ?unidad ;
                  gr:hasValue ?valorSuperficie .

  BIND(IF(?moneda = 'ARS', ?precio / 1235, ?precio) AS ?valorUSD)
  BIND(IF(?unidad = 'ha', ?valorSuperficie * 10000, ?valorSuperficie) AS ?superficieEnM2)
  BIND(?valorUSD / ?superficieEnM2 AS ?valorPorM2)
  BIND(MONTH(?fechaDelListing) AS ?month)
  BIND(YEAR(?fechaDelListing) AS ?year)

  FILTER((?fechaDelListing >= xsd:dateTime('2023-02-01T00:00:00')) &&
         (?fechaDelListing < xsd:dateTime('2024-09-01T00:00:00')))
}
GROUP BY ?year ?month
ORDER BY ?year ?month

prefix io: <http://www.semanticweb.org/luciana/ontologies/2024/8/inmontology#>
prefix brick: <https://brickschema.org/schema/Brick#>
prefix dc: <http://purl.org/dc/elements/1.1/>
prefix dcterms: <http://purl.org/dc/terms/>
prefix foaf: <http://xmlns.com/foaf/0.1/>
prefix gr: <http://purl.org/goodrelations/v1#>
prefix ns: <http://www.w3.org/2003/06/sw-vocab-status/ns#>
prefix owl: <http://www.w3.org/2002/07/owl#>
prefix pronto: <https://raw.githubusercontent.com/fdioguardi/pronto/main/ontology/pronto.owl#>
prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#>
prefix rec: <https://w3id.org/rec#>
prefix sioc: <http://rdfs.org/sioc/ns#>
prefix skos: <http://www.w3.org/2004/02/skos/core#>
prefix time: <http://www.w3.org/2006/time#>
prefix xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (AVG(?priceUSD) AS ?avgPriceUSD)
WHERE {
  ?listing a pronto:RealEstateListing ;
           sioc:about ?realEstate ;
           io:hasFeature ?priceFeature .

  ?realEstate a io:House ;
              io:hasFeature ?addressFeature .

  ?addressFeature a io:Address ;
                  io:hasValue ?postalAddress .

  ?postalAddress a io:PostalAddress ;
                 io:neighborhood io:neighborhood_Manuel_B_Gonnet_district_GBA_Sur_La_Plata_province_GBA_Sur .

  ?priceFeature a io:Price ;
                io:hasValue ?priceSpec .

  ?priceSpec a gr:UnitPriceSpecification ;
             gr:hasCurrency ?currency ;
             gr:hasCurrencyValue ?price ;
             gr:priceType 'BASE'^^xsd:string .

  BIND(
    IF(
      ?currency = 'ARS',
      ?price / 1200,
      ?price
    ) AS ?priceUSD
  )
}
